(() => {
'use strict';
const byId=id=>document.getElementById(id),appearance=document.querySelector('.role-panel:not(.safe-role-panel)');
const preset=document.createElement('div');preset.className='role-autofill';preset.innerHTML='<label>What are you using NX for?<select id="nxUsePreset"><option value="modeling">Everyday part modeling</option><option value="assemblies">Assembly design</option><option value="surfacing">Surface and curve design</option><option value="manufacturing">Manufacturing / CAM preparation</option><option value="documentation">PMI and design documentation</option><option value="minimal">Minimal / distraction-free</option></select></label><button id="applyNxPreset" class="primary" type="button">Autofill suggested tabs</button><p id="nxPresetNote" aria-live="polite">Suggests tabs in Modeling, Sketching, and No Part. Shortcuts stay unchanged. Upload your baseline first to use its available tabs.</p>';
appearance.insertBefore(preset,appearance.querySelector('.visibility-columns'));
byId('applyNxPreset').onclick=()=>{window.NX_ROLE_VISIBILITY.autofill(byId('nxUsePreset').value);byId('nxPresetNote').textContent='Suggested tabs applied. Fine-tune the checkboxes below. Shortcuts are unchanged.';};
const panel=document.createElement('section');panel.className='role-panel merge-panel';panel.innerHTML='<div class="section-title"><div><span class="eyebrow">ROLE MIXER</span><h2>Merge tab visibility</h2><p>Choose your own base role and transfer matching tab visibility from another role.</p></div><button id="loadMergeRoles" class="subtle">Load .mtx roles</button></div><input id="mergeRoleFiles" type="file" accept=".mtx,application/xml,text/xml" multiple hidden><p id="mergeFileStatus" aria-live="polite">Use roles exported from the same NX release. Files stay in this browser.</p><div id="mergeChoices" class="merge-choices"></div><p>Shortcuts, command definitions, tab order, docking, width, and touch settings are retained from your base role.</p><div class="merge-buttons"><button id="previewMerge" class="subtle" disabled>Review merge</button><button id="exportMerge" class="primary" disabled>Download reviewed merge</button></div><pre id="mergeReport" aria-live="polite"></pre>';
appearance.after(panel);
const roles=[],PARTS=[['base','Your base role','All settings start from this role.'],['layout','Ribbon visibility source','Matching tabs only; order and placement stay from the base.'],['sidebar','Sidebar visibility source','Matching normal-mode states only; docking, width, and touch settings stay from the base.']];
const selected=key=>{const value=byId('merge-'+key)?.value;return value===undefined||value===''?null:roles[Number(value)];};
function build(){
 const base=selected('base');if(!base)throw Error('Choose your base role.');
 const layout=selected('layout'),sidebar=selected('sidebar');
 const request={visibility:{ribbon:layout?window.NX_ROLE_PATCH.visibility(layout.xml).ribbon:{},side:sidebar?window.NX_ROLE_PATCH.visibility(sidebar.xml).side:{}},identity:{name:'NX_STUDIO_MERGED_'+base.revision,title:'NX Shortcut Studio — merged tabs'}};
 const result=window.NX_ROLE_PATCH.patch(base.xml,request);
 return {...result,text:result.changes.length?'<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(result.xml):base.text};
}
let reviewed=null;
function invalidate(){reviewed=null;byId('exportMerge').disabled=true;byId('mergeReport').textContent='Review the current selections before downloading.';}
function review(){
 try{reviewed=build();byId('mergeReport').textContent=[reviewed.changes.length+' changes. Unrelated settings passed structural verification.',...reviewed.changes,'',...(reviewed.skipped.length?['Missing targets were kept unchanged:',...reviewed.skipped]:[]),'','Confirm your base and donor use the same NX release before importing.'].join('\n');byId('exportMerge').disabled=!!reviewed.skipped.length;if(reviewed.skipped.length)byId('mergeReport').textContent+='\nExport blocked: choose a source with matching application/tab states.';}
 catch(error){reviewed=null;byId('mergeReport').textContent='Merge blocked: '+error.message;byId('exportMerge').disabled=true;}
}
function renderChoices(){const old=Object.fromEntries(PARTS.map(([key])=>[key,byId('merge-'+key)?.value]));byId('mergeChoices').replaceChildren();for(const [key,label,description] of PARTS){const row=document.createElement('label');row.className='merge-choice';const title=document.createElement('strong');title.textContent=label;const note=document.createElement('small');note.textContent=description;const select=document.createElement('select');select.id='merge-'+key;if(key!=='base'){const option=document.createElement('option');option.value='';option.textContent='Keep base role';select.append(option);}roles.forEach((role,index)=>{const option=document.createElement('option');option.value=String(index);option.textContent=role.name;select.append(option);});if(old[key]!==undefined)select.value=old[key];select.onchange=invalidate;row.append(title,note,select);byId('mergeChoices').append(row);}byId('previewMerge').disabled=roles.length<2;invalidate();}
byId('loadMergeRoles').onclick=()=>byId('mergeRoleFiles').click();
byId('mergeRoleFiles').onchange=async event=>{const failures=[];for(const file of event.target.files){try{if(file.size>10*1024*1024)throw Error('File exceeds 10 MB.');const text=await file.text(),xml=window.NX_ROLE_PATCH.parse(text);roles.push({name:file.name,xml,text,revision:String(Date.now())});}catch(error){failures.push(file.name+': '+error.message);}}renderChoices();byId('mergeFileStatus').textContent=roles.length+' roles loaded. '+failures.join(' | ');event.target.value='';};
byId('previewMerge').onclick=review;
byId('exportMerge').onclick=()=>{try{const current=build();if(!reviewed||current.text!==reviewed.text||current.skipped.length)throw Error('Review the current selections again.');download('NX Shortcut Studio - Merged Visibility.mtx',current.text,'application/xml');}catch(error){invalidate();byId('mergeReport').textContent=error.message;}};
window.NX_ROLE_MERGER={parseRole:window.NX_ROLE_PATCH.parse,build};
})();
